<?php
require_once __DIR__ . '/layout.php';
$month=isset($_GET['month'])&&preg_match('/^\d{4}-\d{2}$/',$_GET['month'])?$_GET['month']:date('Y-m');$dept=trim((string)($_GET['department']??''));$first=$month.'-01';$last=date('Y-m-t',strtotime($first));
$departments=array();$res=$conn->query("SELECT DISTINCT department_name FROM leave_applications WHERE department_name IS NOT NULL AND department_name<>'' ORDER BY department_name");while($res&&$r=$res->fetch_assoc())$departments[]=$r['department_name'];
$where="start_date<='".$conn->real_escape_string($last)."' AND end_date>='".$conn->real_escape_string($first)."' AND status NOT IN ('rejected','cancelled')";if($dept!=='')$where.=" AND department_name='".$conn->real_escape_string($dept)."'";$events=array();$res=$conn->query("SELECT id,employee_name,department_name,leave_type_name,start_date,end_date,status FROM leave_applications WHERE {$where} ORDER BY start_date,employee_name");while($res&&$r=$res->fetch_assoc()){
  $s=max(strtotime($r['start_date']),strtotime($first));$e=min(strtotime($r['end_date']),strtotime($last));for($t=$s;$t<=$e;$t+=86400){$key=date('Y-m-d',$t);if(!isset($events[$key]))$events[$key]=array();$events[$key][]=$r;}
}
$thaiMonths=array(1=>'มกราคม',2=>'กุมภาพันธ์',3=>'มีนาคม',4=>'เมษายน',5=>'พฤษภาคม',6=>'มิถุนายน',7=>'กรกฎาคม',8=>'สิงหาคม',9=>'กันยายน',10=>'ตุลาคม',11=>'พฤศจิกายน',12=>'ธันวาคม');$ts=strtotime($first);$title=$thaiMonths[(int)date('n',$ts)].' '.((int)date('Y',$ts)+543);$prev=date('Y-m',strtotime('-1 month',$ts));$next=date('Y-m',strtotime('+1 month',$ts));$startDow=(int)date('w',$ts);$daysIn=(int)date('t',$ts);$cells=(int)ceil(($startDow+$daysIn)/7)*7;
leave_page_start('ปฏิทินการลา','ตรวจสอบวันลาของบุคลากรและกรองตามหน่วยงาน','calendar');
?>
<section class="leave-card"><div class="leave-card__head"><div><h2>ปฏิทินการลา</h2><p>แสดงทั้งรายการอนุมัติและรายการที่อยู่ระหว่างดำเนินการ โดยระบุสถานะด้วยสี</p></div></div><div class="leave-card__body">
<form class="leave-filter no-print" method="get"><div class="leave-field"><label>เดือน</label><input class="leave-input" type="month" name="month" value="<?=leave_e($month)?>"></div><div class="leave-field"><label>หน่วยงาน</label><select class="leave-select" data-dept-filter name="department"><option value="">ทุกหน่วยงาน</option><?php foreach($departments as $d):?><option value="<?=leave_e($d)?>" <?=$dept===$d?'selected':''?>><?=leave_e($d)?></option><?php endforeach;?></select></div><button class="leave-btn leave-btn--secondary">แสดงข้อมูล</button></form>
<div class="leave-calendar-head" style="margin-top:20px"><a class="leave-btn leave-btn--outline" href="?month=<?=$prev?>&department=<?=urlencode($dept)?>">‹ เดือนก่อน</a><div class="leave-calendar-title"><?=leave_e($title)?></div><a class="leave-btn leave-btn--outline" href="?month=<?=$next?>&department=<?=urlencode($dept)?>">เดือนถัดไป ›</a></div>
<div class="leave-calendar-wrap"><div class="leave-calendar"><?php foreach(array('อาทิตย์','จันทร์','อังคาร','พุธ','พฤหัสบดี','ศุกร์','เสาร์') as $dow):?><div class="leave-calendar__dow"><?=$dow?></div><?php endforeach;?><?php for($cell=0;$cell<$cells;$cell++):$day=$cell-$startDow+1;$valid=$day>=1&&$day<=$daysIn;$dateKey=$valid?date('Y-m-', $ts).str_pad((string)$day,2,'0',STR_PAD_LEFT):'';?><div class="leave-calendar__day <?=$valid?'':'is-other'?>"><?php if($valid):?><div class="leave-calendar__number"><?=$day?></div><?php foreach(isset($events[$dateKey])?$events[$dateKey]:array() as $ev):$pending=$ev['status']!=='approved';?><div class="leave-event <?=$pending?'pending':''?>"><?=leave_e($ev['employee_name'])?><small><?=leave_e($ev['leave_type_name'])?> · <?=leave_e($ev['department_name'])?><?=$pending?' · รอดำเนินการ':''?></small></div><?php endforeach;?><?php endif;?></div><?php endfor;?></div></div>
</div></section>
<?php leave_page_end(); ?>
